    /// <summary>
    /// The list of traffic sources to attach to this Auto Scaling group. You can use any of the following as traffic sources for an Auto Scaling group: Classic Load Balancer, Application Load Balancer, Gateway Load Balancer, Network Load Balancer, and VPC Lattice. (structure) Identifying information for a traffic source. Identifier -&gt; (string) [required] Identifies the traffic source. For Application Load Balancers, Gateway Load Balancers, Net- work Load Balancers, and VPC Lattice, this will be the Amazon Resource Name (ARN) for a target group in this account and Region. For Classic Load Balancers, this will be the name of the Classic Load Balancer in this account and Region. For example: o Application Load Balancer ARN: arn:aws:elasticloadbalanc- ing:us-west-2:123456789012:targetgroup/my-tar- gets/1234567890123456 o Classic Load Balancer name: my-classic-load-balancer o VPC Lattice ARN: arn:aws:vpc-lat- tice:us-west-2:123456789012:targetgroup/tg-1234567890123456 To get the ARN of a target group for a Application Load Bal- ancer, Gateway Load Balancer, or Network Load Balancer, or the name of a Classic Load Balancer, use the Elastic Load Balancing DescribeTargetGroups and DescribeLoadBalancers API operations. To get the ARN of a target group for VPC Lattice, use the VPC Lattice GetTargetGroup API operation. Constraints: o min: 1 o max: 511 o pattern: [\u0020-\uD7FF\uE000-\uFFFD\uD800\uDC00-\uDBFF\uDFFF\r\n\t]* Type -&gt; (string) Provides additional context for the value of Identifier . The following lists the valid values: o elb if Identifier is the name of a Classic Load Balancer. o elbv2 if Identifier is the ARN of an Application Load Bal- ancer, Gateway Load Balancer, or Network Load Balancer tar- get group. o vpc-lattice if Identifier is the ARN of a VPC Lattice tar- get group. Required if the identifier is the name of a Classic Load Bal- ancer. Constraints: o min: 1 o max: 511 o pattern: [\u0020-\uD7FF\uE000-\uFFFD\uD800\uDC00-\uDBFF\uDFFF\r\n\t]* Shorthand Syntax: Identifier=string,Type=string ... JSON Syntax: [ { "Identifier": "string", "Type": "string" } ... ]
    /// </summary>
    [CliOption("--traffic-sources", GroupValues = true)]
    public IEnumerable<string>? TrafficSources { get; set; }

    /// <summary>
    /// An instance maintenance policy. For more information, see Set in- stance maintenance policy in the Amazon EC2 Auto Scaling User Guide . MinHealthyPercentage -&gt; (integer) Specifies the lower threshold as a percentage of the desired ca- pacity of the Auto Scaling group. It represents the minimum per- centage of the group to keep in service, healthy, and ready to use to support your workload when replacing instances. Value range is 0 to 100. To clear a previously set value, specify a value of -1 . Constraints: o min: -1 o max: 100 MaxHealthyPercentage -&gt; (integer) Specifies the upper threshold as a percentage of the desired ca- pacity of the Auto Scaling group. It represents the maximum per- centage of the group that can be in service and healthy, or pending, to support your workload when replacing instances. Value range is 100 to 200. To clear a previously set value, specify a value of -1 . Both MinHealthyPercentage and MaxHealthyPercentage must be spec- ified, and the difference between them cannot be greater than 100. A large range increases the number of instances that can be replaced at the same time. Constraints: o min: -1 o max: 200 Shorthand Syntax: MinHealthyPercentage=integer,MaxHealthyPercentage=integer JSON Syntax: { "MinHealthyPercentage": integer, "MaxHealthyPercentage": integer }
    /// </summary>
    [CliOption("--instance-maintenance-policy")]
    public string? InstanceMaintenancePolicy { get; set; }

    /// <summary>
    /// The instance capacity distribution across Availability Zones. CapacityDistributionStrategy -&gt; (string) If launches fail in an Availability Zone, the following strate- gies are available. The default is balanced-best-effort . o balanced-only - If launches fail in an Availability Zone, Auto Scaling will continue to attempt to launch in the unhealthy zone to preserve a balanced distribution. o balanced-best-effort - If launches fail in an Availability Zone, Auto Scaling will attempt to launch in another healthy Availability Zone instead. o reservations-then-balanced - Auto Scaling will first attempt to launch into your Capacity Reservations, and then balance any remaining capacity across healthy Availability Zones. Possible values: o balanced-only o balanced-best-effort o reservations-then-balanced Shorthand Syntax: CapacityDistributionStrategy=string JSON Syntax: { "CapacityDistributionStrategy": "balanced-only"|"balanced-best-effort"|"reservations-then-balanced" }
    /// </summary>
    [CliOption("--availability-zone-distribution")]
    public string? AvailabilityZoneDistribution { get; set; }

    /// <summary>
    /// The policy for Availability Zone impairment. ZonalShiftEnabled -&gt; (boolean) If true , enable zonal shift for your Auto Scaling group. ImpairedZoneHealthCheckBehavior -&gt; (string) Specifies the health check behavior for the impaired Availabil- ity Zone in an active zonal shift. If you select Replace un- healthy , instances that appear unhealthy will be replaced in all Availability Zones. If you select Ignore unhealthy , in- stances will not be replaced in the Availability Zone with the active zonal shift. For more information, see Auto Scaling group zonal shift in the Amazon EC2 Auto Scaling User Guide . Possible values: o ReplaceUnhealthy o IgnoreUnhealthy Shorthand Syntax: ZonalShiftEnabled=boolean,ImpairedZoneHealthCheckBehavior=string JSON Syntax: { "ZonalShiftEnabled": true|false, "ImpairedZoneHealthCheckBehavior": "ReplaceUnhealthy"|"IgnoreUnhealthy" }
    /// </summary>
    [CliOption("--availability-zone-impairment-policy")]
    public string? AvailabilityZoneImpairmentPolicy { get; set; }

    /// <summary>
    /// If you enable zonal shift with cross-zone disabled load balancers, capacity could become imbalanced across Availability Zones. To skip the validation, specify true . For more information, see Auto Scal- ing group zonal shift in the Amazon EC2 Auto Scaling User Guide .
    /// </summary>
    [CliFlag("--skip-zonal-shift-validation", NegatedName = "--no-skip-zonal-shift-validation")]
    public bool? SkipZonalShiftValidation { get; set; }

    /// <summary>
    /// The capacity reservation specification for the Auto Scaling group. CapacityReservationPreference -&gt; (string) The capacity reservation preference. The following options are available: o capacity-reservations-only - Auto Scaling will only launch in- stances into a Capacity Reservation or Capacity Reservation resource group. If capacity isn't available, instances will fail to launch. o capacity-reservations-first - Auto Scaling will try to launch instances into a Capacity Reservation or Capacity Reservation resource group first. If capacity isn't available, instances will run in On-Demand capacity. o none - Auto Scaling will not launch instances into a Capacity Reservation. Instances will run in On-Demand capacity. o default - Auto Scaling uses the Capacity Reservation prefer- ence from your launch template or an open Capacity Reserva- tion. Possible values: o capacity-reservations-only o capacity-reservations-first o none o default CapacityReservationTarget -&gt; (structure) Describes a target Capacity Reservation or Capacity Reservation resource group. CapacityReservationIds -&gt; (list) The Capacity Reservation IDs to launch instances into. (string) Constraints: o min: 1 o max: 255 o pattern: [A-Za-z0-9\-_\/]+ CapacityReservationResourceGroupArns -&gt; (list) The resource group ARNs of the Capacity Reservation to launch instances into. (string) Constraints: o min: 1 o max: 1600 o pattern: [\u0020-\uD7FF\uE000-\uFFFD\uD800\uDC00-\uDBFF\uDFFF\r\n\t]* Shorthand Syntax: CapacityReservationPreference=string,CapacityReservationTarget={CapacityReservationIds=[string,string],CapacityReservationResourceGroupArns=[string,string]} JSON Syntax: { "CapacityReservationPreference": "capacity-reservations-only"|"capacity-reservations-first"|"none"|"default", "CapacityReservationTarget": { "CapacityReservationIds": ["string", ...], "CapacityReservationResourceGroupArns": ["string", ...] } }
    /// </summary>
    [CliOption("--capacity-reservation-specification")]
    public string? CapacityReservationSpecification { get; set; }

    /// <summary>
    /// The instance lifecycle policy for the Auto Scaling group. This pol- icy controls instance behavior when an instance transitions through its lifecycle states. Configure retention triggers to specify when instances should move to a Retained state instead of automatic ter- mination. For more information, see Control instance retention with instance lifecycle policies in the Amazon EC2 Auto Scaling User Guide . NOTE: Instances in a Retained state will continue to incur standard EC2 charges until terminated. RetentionTriggers -&gt; (structure) Specifies the conditions that trigger instance retention behav- ior. These triggers determine when instances should move to a Retained state instead of automatic termination. This allows you to maintain control over instance management when lifecycles transition and operations fail. TerminateHookAbandon -&gt; (string) Specifies the action when a termination lifecycle hook is abandoned due to failure, timeout, or explicit abandonment (calling CompleteLifecycleAction). Set to retain to move instances to a retained state. Set to terminate for default termination behavior. Retained instances don't count toward desired capacity and remain until you call TerminateInstanceInAutoScalingGroup . Possible values: o retain o terminate Shorthand Syntax: RetentionTriggers={TerminateHookAbandon=string} JSON Syntax: { "RetentionTriggers": { "TerminateHookAbandon": "retain"|"terminate" } }
    /// </summary>
    [CliOption("--instance-lifecycle-policy")]
    public string? InstanceLifecyclePolicy { get; set; }

    /// <summary>
    /// The entity that manages the Auto Scaling group. If you specify this parameter, Amazon EC2 Auto Scaling passes the operator identity to EC2 for instance launches and only allows the designated operator to make changes to the Auto Scaling group. All mutating API calls from non-operator callers are rejected with an AccessDenied exception. Principal -&gt; (string) [required] The service principal that is authorized to manage the Auto Scaling group. When an operator is specified, only the desig- nated operator service principal can make mutating changes to the Auto Scaling group. Constraints: o min: 1 o max: 128 Shorthand Syntax: Principal=string JSON Syntax: { "Principal": "string" }
    /// </summary>
    [CliOption("--operator")]
    public string? Operator { get; set; }

    [CliOption("--cli-input-json")]
    public string? CliInputJson { get; set; }

    [CliOption("--generate-cli-skeleton")]
    public string? GenerateCliSkeleton { get; set; }

    /// <inheritdoc />
    IEnumerable<ValidationResult> IValidatableObject.Validate(ValidationContext validationContext)
    {
        if (_requiresAlternateInput && !(!string.IsNullOrWhiteSpace(CliInputJson) || GenerateCliSkeleton is "input" or "yaml-input"))
        {
            yield return new ValidationResult("An alternate input must remain selected for an instance created without required operation values.");
            yield break;
        }

        if (!string.IsNullOrWhiteSpace(CliInputJson) || GenerateCliSkeleton is "input" or "yaml-input")
        {
            yield break;
        }

    }

